INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Stakeholder wichtige Akteure im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Beeinflussen Projektverlauf"}, {"text": "Nein", "correct": false, "because": "Sie sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Stakeholder im Projekt?', 3, '[{"text": "Interessen am Projekterfolg sichern", "correct": true, "because": "Haben Einfluss"}, {"text": "Projekt direkt umsetzen", "correct": false, "because": "Teamaufgabe"}, {"text": "Kosten allein tragen", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Stakeholder haben Einfluss auf das Projekt. b) Sie führen die tägliche Arbeit aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Teamaufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gruppen können Stakeholder sein?', 4, '[{"text": "Auftraggeber", "correct": true, "because": "Definiert Ziele"}, {"text": "Unbeteiligte Personen", "correct": false, "because": "Kein Einfluss"}, {"text": "Teammitglieder", "correct": true, "because": "Umsetzen Projekt"}, {"text": "Externe Partner", "correct": true, "because": "Beeinflussen Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Stakeholder erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Einfluss und Interessen fehlen"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Stakeholder in der Initiierung?', 3, '[{"text": "Anforderungen und Erwartungen einbringen", "correct": true, "because": "Formen Ziele"}, {"text": "Tägliche Arbeit steuern", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Projekt finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Stakeholder nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte betreffen"}, {"text": "Ja", "correct": false, "because": "Universelle Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung haben Stakeholder?', 3, '[{"text": "Feedback und Unterstützung geben", "correct": true, "because": "Beeinflussen Erfolg"}, {"text": "Technische Umsetzung", "correct": false, "because": "Teamaufgabe"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Projektleiteraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Stakeholder können Entscheidungen beeinflussen. b) Sie sind immer extern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Berücksichtigung der Stakeholder?', 3, '[{"text": "Interessenkonflikte entstehen", "correct": true, "because": "Fehlende Abstimmung"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Unzufriedenheit möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Projektleiter ohne Stakeholder arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Abstimmung nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Stakeholder-Aufgabe?', 3, '[{"text": "Kunde liefert Anforderungen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwer macht etwas", "correct": false, "because": "Zu vage"}, {"text": "Team soll Feedback geben", "correct": false, "because": "Keine klare Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Stakeholder nur in der Initiierung wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Über alle Phasen relevant"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Stakeholder?', 4, '[{"text": "Interessen am Projekt", "correct": true, "because": "Beeinflussen Erfolg"}, {"text": "Unbeteiligte Haltung", "correct": false, "because": "Widerspricht Definition"}, {"text": "Einflussmöglichkeiten", "correct": true, "because": "Gestalten Verlauf"}, {"text": "Kommunikationsbedarf", "correct": true, "because": "Fördern Abstimmung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Stakeholder dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Klarheit und Nachweis"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Stakeholder-Verwaltung?', 3, '[{"text": "Stakeholder-Analyse", "correct": true, "because": "Identifiziert Einfluss"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Liste", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Stakeholder-Abstimmung erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Interessenkonflikte drohen"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Arbeit mit Stakeholdern?', 3, '[{"text": "Unklare Erwartungen", "correct": true, "because": "Verhindern Abstimmung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Planung"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Stakeholder beeinflussen die Abnahme. b) Sie sind nur extern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Stakeholder-Beteiligung?', 3, '[{"text": "Projektakzeptanz steigern", "correct": true, "because": "Fördert Zustimmung"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Unterstützung", "correct": false, "because": "Fördert Erfolg"}]');
